import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int M = in.nextInt();
        String soz = in.next();
        int h = 0;
        for (char c : soz.toCharArray()) {
            h = (h * 31 + c) % M;
        }
        System.out.println(h);
    }
}

